stages.planning:
{
  "target_competitors": [
    "CloudScale AI",
    "DataPulse Systems",
    "NexusOps Technologies",
    "Veloce Security"
  ],
  "evaluation_dimensions": [
    {
      "name": "Architecture",
      "description": "Technical stack, deployment model (cloud\u2011native, hybrid, on\u2011prem), scalability mechanisms, and integration points with enterprise ecosystems."
    },
    {
      "name": "Enterprise Latency / Throughput",
      "description": "Measured end\u2011to\u2011end latency under enterprise workloads, sustained throughput, and performance consistency across regions and load spikes."
    },
    {
      "name": "Pricing Predictability",
      "description": "Clarity of pricing tiers, presence of usage\u2011based vs. flat\u2011rate models, hidden fees, and the ability to forecast quarterly/annual spend with confidence."
    },
    {
      "name": "Advertised vs. Actual SLA",
      "description": "Comparison of vendor\u2011published service\u2011level agreements (availability, latency, support response) against third\u2011party audit results and customer\u2011reported breach incidents."
    },
    {
      "name": "On-Prem / Hybrid Readiness",
      "description": "Availability of on\u2011premise or hybrid deployment options, required hardware, integration complexity, and support for data sovereignty requirements."
    },
    {
      "name": "Customer Sentiment & Trust",
      "description": "Aggregate sentiment from reviews, case studies, churn rates, and analyst trust scores; includes qualitative insights on support quality and roadmap transparency."
    }
  ],
  "evidence_gathering_plan": {
    "sources": [
      {
        "type": "Vendor whitepapers & technical datasheets",
        "purpose": "Obtain official architecture details, advertised performance metrics, and pricing structures."
      },
      {
        "type": "Third\u2011party analyst reports (e.g., Gartner, Forrester)",
        "purpose": "Validate performance claims, SLA adherence, and market positioning."
      },
      {
        "type": "Independent benchmark labs (e.g., Cloud Spectator, TechEmpower)",
        "purpose": "Collect empirical latency and throughput data under controlled enterprise workloads."
      },
      {
        "type": "Customer review platforms (G2, TrustRadius, Reddit, LinkedIn groups)",
        "purpose": "Gauge real\u2011world sentiment, perceived pricing predictability, and support experiences."
      },
      {
        "type": "Regulatory filings & financial disclosures",
        "purpose": "Cross\u2011check pricing models, revenue recognition, and any disclosed SLA breach penalties."
      },
      {
        "type": "Direct stakeholder interviews (CTO, DevOps leads, procurement)",
        "purpose": "Capture nuanced insights on on\u2011prem readiness, integration challenges, and trust factors."
      }
    ],
    "methodology": [
      {
        "step": "Define data collection parameters",
        "actions": [
          "Establish workload profiles representative of target enterprise use cases.",
          "Set latency and throughput thresholds for each profile.",
          "Create a pricing matrix (per\u2011core, per\u2011TB, subscription tiers)."
        ]
      },
      {
        "step": "Collect primary data",
        "actions": [
          "Download and catalog all vendor\u2011published materials.",
          "Run benchmark suites on each platform using identical test rigs.",
          "Extract SLA language verbatim for later comparison."
        ]
      },
      {
        "step": "Validate and normalize data",
        "actions": [
          "Cross\u2011reference benchmark results with third\u2011party reports.",
          "Normalize pricing to a common unit (e.g., $/M compute\u2011hours).",
          "Map SLA terms to a standardized scoring rubric."
        ]
      },
      {
        "step": "Analyze & score",
        "actions": [
          "Score each dimension on a 1\u20115 scale using weighted criteria.",
          "Perform sensitivity analysis on pricing predictability under variable usage.",
          "Calculate variance between advertised and actual SLA performance."
        ]
      },
      {
        "step": "Synthesize findings",
        "actions": [
          "Compile a comparative matrix with visual heat\u2011maps.",
          "Draft narrative insights highlighting strengths, gaps, and risk factors.",
          "Prepare an executive summary with actionable recommendations."
        ]
      }
    ]
  }
}

